{"packet_id":"D004-01","doc_id":"D004","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley owner move-in eviction relocation assistance (2026 inflationary adjustment)","requirement":"A landlord who evicts a tenant for owner move-in must pay relocation assistance, adjusted yearly for inflation. From January 1, 2026 the standard payment is $19,413 and the additional payment for qualifying households is $6,471.","key_value":"$19,413 standard; $6,471 additional for qualifying households; 1.5% CPI adjustment for 2026","coverage_conditions":"Tenants evicted for owner move-in under the Berkeley Rent Stabilization and Good Cause for Eviction Ordinance; payments indexed to inflation.","applicability":{"conditions":[],"per_tenancy":"Tenancy ended by an owner move-in eviction","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Annual increases for owner move-in and Ellis Act eviction relocation assistance payments go into effect January 1, 2026.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D004-01","doc_id":"D004","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley Ellis Act eviction relocation assistance (2026 inflationary adjustment)","requirement":"The Ellis Implementation Ordinance requires relocation assistance when a tenant is evicted so the owner can remove the property from the rental market. From January 1, 2026 the standard payment is $19,413 and the additional payment for qualifying households is $6,471.","key_value":"$19,413 standard; $6,471 additional for qualifying households","coverage_conditions":"Tenants evicted under the Ellis Act so the owner can remove a property from the rental housing market; payments indexed to inflation.","applicability":{"conditions":[],"per_tenancy":"Tenancy ended by an Ellis Act eviction","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Ellis Implementation Ordinance","quoted_span":"The Ellis Implementation Ordinance requires the same relocation assistance payments for tenants evicted so the owner can remove a property from the rental housing market.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
